[patterns/application/micro-frontend/PTN-APP-MFE-015-testing-strategy-pattern.md#phase-1-unit-testing-setup-week-1]

#### Phase 1: Unit Testing Setup (Week 1)

1. **Install Vitest and React Testing Library**

   ```bash
   npm install --save-dev vitest @testing-library/react @testing-library/jest-dom @testing-library/user-event jsdom
   ```

2. **Configure Vitest**

   ```typescript
   // vite.config.ts
   import { defineConfig } from 'vite';
   import react from '@vitejs/plugin-react';

   export default defineConfig({
     plugins: [react()],
     test: {
       globals: true,
       environment: 'jsdom',
       setupFiles: './src/test/setup.ts',
       coverage: {
         provider: 'v8',
         reporter: ['text', 'json', 'html'],
         exclude: ['node_modules/', 'src/test/']
       }
     }
   });
   ```

3. **Setup Test Utilities**

   ```typescript
   // src/test/setup.ts
   import '@testing-library/jest-dom';
   import { cleanup } from '@testing-library/react';
   import { afterEach } from 'vitest';

   afterEach(() => {
     cleanup();
   });
   ```

4. **Write First Unit Test**

   ```typescript
   // src/components/Button.test.tsx
   import { render, screen } from '@testing-library/react';
   import userEvent from '@testing-library/user-event';
   import { describe, it, expect, vi } from 'vitest';
   import { Button } from './Button';

   describe('Button', () => {
     it('renders with text', () => {
       render(<Button>Submit Claim</Button>);
       expect(screen.getByText('Submit Claim')).toBeInTheDocument();
     });

     it('calls onClick when clicked', async () => {
       const handleClick = vi.fn();
       const user = userEvent.setup();

       render(<Button onClick={handleClick}>Click Me</Button>);
       await user.click(screen.getByRole('button'));

       expect(handleClick).toHaveBeenCalledOnce();
     });

     it('is disabled when loading', () => {
       render(<Button loading>Submit</Button>);
       expect(screen.getByRole('button')).toBeDisabled();
     });
   });
   ```

