[patterns/application/micro-frontend/PTN-APP-MFE-015-testing-strategy-pattern.md#phase-2-integration-testing-week-2]

#### Phase 2: Integration Testing (Week 2)

1. **Install MSW (Mock Service Worker)**

   ```bash
   npm install --save-dev msw
   ```

2. **Setup API Mocks**

   ```typescript
   // src/test/mocks/handlers.ts
   import { http, HttpResponse } from 'msw';

   export const handlers = [
     http.get('/api/claims', () => {
       return HttpResponse.json([
         { id: 'CLM001', amount: 1250.00, status: 'Approved' },
         { id: 'CLM002', amount: 850.50, status: 'Pending' }
       ]);
     }),

     http.post('/api/claims', async ({ request }) => {
       const claim = await request.json();
       return HttpResponse.json(
         { id: 'CLM003', ...claim, status: 'Submitted' },
         { status: 201 }
       );
     })
   ];
   ```

3. **Integration Test Example**

   ```typescript
   // src/pages/ClaimsPage.test.tsx
   import { render, screen, waitFor } from '@testing-library/react';
   import userEvent from '@testing-library/user-event';
   import { setupServer } from 'msw/node';
   import { handlers } from '../test/mocks/handlers';
   import { ClaimsPage } from './ClaimsPage';

   const server = setupServer(...handlers);

   beforeAll(() => server.listen());
   afterEach(() => server.resetHandlers());
   afterAll(() => server.close());

   it('loads and displays claims', async () => {
     render(<ClaimsPage />);

     expect(screen.getByText('Loading...')).toBeInTheDocument();

     await waitFor(() => {
       expect(screen.getByText('CLM001')).toBeInTheDocument();
       expect(screen.getByText('$1,250.00')).toBeInTheDocument();
     });
   });
   ```

