[patterns/application/micro-frontend/PTN-APP-MFE-015-testing-strategy-pattern.md#phase-3-e2e-testing-week-3]

#### Phase 3: E2E Testing (Week 3)

1. **Install Playwright**

   ```bash
   npm install --save-dev @playwright/test
   npx playwright install
   ```

2. **Configure Playwright**

   ```typescript
   // playwright.config.ts
   import { defineConfig, devices } from '@playwright/test';

   export default defineConfig({
     testDir: './e2e',
     fullyParallel: true,
     forbidOnly: !!process.env.CI,
     retries: process.env.CI ? 2 : 0,
     workers: process.env.CI ? 1 : undefined,
     reporter: 'html',
     use: {
       baseURL: 'http://localhost:3000',
       trace: 'on-first-retry',
       screenshot: 'only-on-failure'
     },
     projects: [
       { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
       { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
       { name: 'webkit', use: { ...devices['Desktop Safari'] } }
     ],
     webServer: {
       command: 'npm run dev',
       url: 'http://localhost:3000',
       reuseExistingServer: !process.env.CI
     }
   });
   ```

3. **Write E2E Test**

    ```typescript
    // e2e/claims-submission.spec.ts
    import { test, expect } from '@playwright/test';

    test('submit new claim', async ({ page }) => {
      await page.goto('/claims/new');

      // Fill claim form
      await page.getByLabel('Member ID').fill('M123456');
      await page.getByLabel('Service Date').fill('2026-01-15');
      await page.getByLabel('Amount').fill('1250.00');
      await page.getByLabel('Diagnosis Code').fill('J06.9');

      // Submit
      await page.getByRole('button', { name: 'Submit Claim' }).click();

      // Verify success
      await expect(page.getByText('Claim submitted successfully')).toBeVisible();
      await expect(page).toHaveURL(/\/claims\/CLM\d+/);
    });
    ```

